reactiveclass Counter(c1, c2) {
	knownrebecs {
		Client c1;
		Client c2;
	}

	statevars {
		int count;
		Client client1;
		Client client2;
	}

	msgsrv initial() {
		count = 0;
		client1 = c1;
		client2 = c2;
	}

	msgsrv Increment(Client sender) {
		count = count + 1;
		sender.ValueResponse(count);
	}

	msgsrv Decrement(Client sender) {
		count = count - 1;
		sender.ValueResponse(count);
	}

	msgsrv GetValue(Client sender) {
		sender.ValueResponse(count);
	}
}

reactiveclass Client(counter) {
	knownrebecs {
		Counter counter;
	}

	statevars {
		int clientId;
	}

	msgsrv initial(int id) {
		clientId = id;
	}

	msgsrv Start() {
		counter.Increment(this) after(1);
